// 解析DeepSeek API响应
const response = $input.item.json;
const assistantMessage = response.choices?.[0]?.message || {};
const toolCalls = assistantMessage.tool_calls || [];
const content = assistantMessage.content || '';

return {
  json: {
    content: content,
    tool_calls: toolCalls,
    has_tool_calls: toolCalls.length > 0,
    full_response: response
  }
};

// 提取工具调用
const toolCalls = $input.item.json.tool_calls || [];
const results = [];

for (const toolCall of toolCalls) {
  const toolName = toolCall.function.name;
  let toolArgs = {};
  try {
    toolArgs = JSON.parse(toolCall.function.arguments || '{}');
  } catch (e) {
    toolArgs = {};
  }

  results.push({
    tool_name: toolName,
    tool_arguments: toolArgs,
    tool_call_id: toolCall.id
  });
}

return results.map(item => ({ json: item }));

// 合并工具调用结果
const toolResults = $input.all();
const originalMessages = $('准备消息').item.json.messages;
const assistantMessage = $('解析响应').item.json.full_response.choices[0].message;

// 构建工具调用消息
const toolMessages = [];
for (const result of toolResults) {
  const toolCall = assistantMessage.tool_calls.find(
    tc => tc.function.name === result.json.tool_name
  );

  if (toolCall) {
    toolMessages.push({
      role: 'assistant',
      content: null,
      tool_calls: [toolCall]
    });

    toolMessages.push({
      role: 'tool',
      content: JSON.stringify(result.json),
      tool_call_id: toolCall.id
    });
  }
}

// 合并所有消息
const allMessages = [...originalMessages, ...toolMessages];

return {
  json: {
    messages: allMessages
  }
};

// 提取最终回复
const response = $input.item.json;
const finalMessage = response.choices?.[0]?.message?.content || '';

return {
  json: {
    message: finalMessage
  }
};
